/** Shared domain types with the backend. */

export type BloomLevel = 'remember' | 'understand' | 'apply' | 'analyze' | 'evaluate' | 'create'

export type Difficulty = 'easy' | 'medium' | 'hard'

export type QuestionType =
  | 'multiple_choice'
  | 'true_false'
  | 'short_answer'
  | 'essay'
  | 'fill_in_blank'
  | 'select_all'

export interface AnswerOption {
  text: string
  is_correct: boolean
}

/** Item generated by the LLM (strict contract with the backend). */
export interface GeneratedItem {
  topic: string
  subtopic?: string | null
  bloom_level: BloomLevel
  difficulty: Difficulty
  question_type: QuestionType
  statement: string
  options: AnswerOption[]
  expected_answer: string
  solution_explanation: string
  points: number
}

/** Question from the bank (row of generated_questions). */
export interface Question {
  id: string
  subject_id: string
  topic: string
  subtopic?: string | null
  bloom_level: string
  difficulty: string
  question_type: string | null
  question_text: string
  options: AnswerOption[] | null
  expected_answer: string | null
  solution_explanation: string | null
  points: number | null
  verified_by_human: boolean
  verified_by_ai: boolean
  ai_review_notes: string | null
  ai_review_priority: 'high' | 'medium' | 'low' | null
  source: string
  created_at: string
}

/** Question enriched with its generator LLM audit fields (bank export). */
export interface BankExportQuestion extends Question {
  prompt: string | null
  thinking: string | null
  generation_model: string | null
}

/** Downloadable question bank (GET /subjects/{id}/questions/export). */
export interface BankExport {
  subject: string
  exported_at: string
  total_questions: number
  thinking_capture_enabled: boolean
  questions: BankExportQuestion[]
}

/** Registered subject. */
export interface Subject {
  id: string
  name: string
}

/** Exam blueprint (exam structure). */
export interface ExamBlueprint {
  subject_id: string
  total_questions: number
  bloom_distribution: Partial<Record<BloomLevel, number>>
  difficulty_distribution: Partial<Record<Difficulty, number>>
  topics_weight: Record<string, number>
  estimated_duration_minutes: number
  metadata?: {
    title?: string
    instructions?: string
    num_versions?: number
    [key: string]: unknown
  }
}

/** Generated exam. */
export interface Exam {
  id: string
  subject_id: string
  subject_name: string
  name?: string
  blueprint: ExamBlueprint
  items: GeneratedItem[]
  num_versions?: number
  pdf_paths: string[]
  zip_path?: string | null
  created_at: string
}
